import{_ as u,I as h,o as g,c as r,b6 as n,J as i}from"./chunks/framework.BUXTSoD9.js";const k=JSON.parse('{"title":"Trực quan hóa Dữ liệu và Bảng điều khiển","description":"","frontmatter":{},"headers":[],"relativePath":"vi-vn/appendix/5-data/data-visualization.md","filePath":"vi-vn/appendix/5-data/data-visualization.md"}'),d={name:"vi-vn/appendix/5-data/data-visualization.md"};function o(l,t,e,s,b,p){const a=h("ChartTypeSelectorDemo"),c=h("DashboardLayoutDemo");return g(),r("div",null,[t[0]||(t[0]=n('<h1 id="truc-quan-hoa-du-lieu-va-bang-đieu-khien" tabindex="-1">Trực quan hóa Dữ liệu và Bảng điều khiển <a class="header-anchor" href="#truc-quan-hoa-du-lieu-va-bang-đieu-khien" aria-label="Permalink to “Trực quan hóa Dữ liệu và Bảng điều khiển”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Lời nói đầu</p><p><strong>Một biểu đồ tốt đáng giá ngàn dòng dữ liệu.</strong> Trực quan hóa dữ liệu là việc chuyển đổi những con số trừu tượng thành biểu đạt trực quan sinh động, giúp con người có thể hiểu câu chuyện đằng sau dữ liệu chỉ trong vài giây. Từ biểu đồ Excel đến màn hình giám sát Grafana, trực quan hóa có mặt ở khắp nơi.</p></div><p><strong>Bài viết này sẽ giúp bạn học được gì?</strong></p><p>Sau khi học xong chương này, bạn sẽ đạt được:</p><ul><li><strong>Lựa chọn biểu đồ</strong>: Chọn loại biểu đồ phù hợp nhất dựa trên mục đích dữ liệu</li><li><strong>Nguyên tắc trực quan hóa</strong>: Nắm vững các nguyên tắc thiết kế cốt lõi của trực quan hóa dữ liệu</li><li><strong>Thiết kế bảng điều khiển</strong>: Hiểu các mẫu bố cục của các loại bảng điều khiển khác nhau</li><li><strong>Hệ sinh thái công cụ</strong>: Quen thuộc với định vị và lựa chọn các công cụ trực quan hóa phổ biến</li><li><strong>Bẫy phổ biến</strong>: Tránh các biểu đồ gây hiểu lầm và các lỗi trực quan hóa thường gặp</li></ul><table tabindex="0"><thead><tr><th>Chương</th><th>Nội dung</th><th>Khái niệm cốt lõi</th></tr></thead><tbody><tr><td><strong>Chương 1</strong></td><td>Lựa chọn loại biểu đồ</td><td>So sánh, xu hướng, tỷ trọng, phân bố, quan hệ</td></tr><tr><td><strong>Chương 2</strong></td><td>Nguyên tắc thiết kế trực quan hóa</td><td>Tỷ lệ mực dữ liệu, tính nhất quán, khả năng đọc</td></tr><tr><td><strong>Chương 3</strong></td><td>Bố cục bảng điều khiển</td><td>Tổng quan, so sánh, phân tích chuyên sâu, thời gian thực</td></tr><tr><td><strong>Chương 4</strong></td><td>Lựa chọn công cụ</td><td>ECharts, D3, Grafana, Metabase</td></tr><tr><td><strong>Chương 5</strong></td><td>Bẫy phổ biến</td><td>Cắt đứt trục tọa độ, biểu đồ tròn 3D, lạm dụng màu sắc</td></tr></tbody></table><hr><h2 id="_0-toan-canh-tai-sao-can-truc-quan-hoa" tabindex="-1">0. Toàn cảnh: Tại sao cần trực quan hóa? <a class="header-anchor" href="#_0-toan-canh-tai-sao-can-truc-quan-hoa" aria-label="Permalink to “0. Toàn cảnh: Tại sao cần trực quan hóa?”">​</a></h2><p>Não bộ con người xử lý thông tin trực quan nhanh hơn nhiều so với văn bản. Một biểu đồ đường có thể giúp bạn nhanh chóng nhận thấy &quot;doanh thu tháng trước đang giảm&quot;, trong khi cùng một thông tin nếu được trình bày dưới dạng bảng, bạn có thể cần so sánh từng dòng mới có thể kết luận.</p><p>Giá trị cốt lõi của trực quan hóa:</p><ul><li><strong>Phát hiện mẫu</strong>: Xu hướng, chu kỳ, giá trị ngoại lai hiển hiện rõ ràng trong biểu đồ</li><li><strong>Hỗ trợ ra quyết định</strong>: Giúp người không chuyên kỹ thuật cũng có thể hiểu dữ liệu, tham gia ra quyết định</li><li><strong>Hiệu quả giao tiếp</strong>: Một hình ảnh đáng giá ngàn lời nói, giảm thiểu sự mơ hồ trong việc diễn giải dữ liệu</li></ul><div class="tip custom-block"><p class="custom-block-title">Trực quan hóa ≠ Đẹp mắt</p><p>Mục tiêu của trực quan hóa là <strong>truyền đạt thông tin</strong>, không phải phô diễn kỹ thuật. Một biểu đồ cột giản dị nhưng chính xác, có giá trị hơn nhiều so với một biểu đồ 3D hào nhoáng nhưng khó hiểu.</p></div><hr><h2 id="_1-lua-chon-loai-bieu-đo-dung-đung-bieu-đo-ke-đung-cau-chuyen" tabindex="-1">1. Lựa chọn loại biểu đồ: Dùng đúng biểu đồ kể đúng câu chuyện <a class="header-anchor" href="#_1-lua-chon-loai-bieu-đo-dung-đung-bieu-đo-ke-đung-cau-chuyen" aria-label="Permalink to “1. Lựa chọn loại biểu đồ: Dùng đúng biểu đồ kể đúng câu chuyện”">​</a></h2><p>Bước đầu tiên để chọn biểu đồ không phải là &quot;tôi thích biểu đồ nào&quot;, mà là &quot;tôi muốn truyền đạt thông tin gì&quot;. Các mục đích dữ liệu khác nhau tương ứng với các loại biểu đồ tối ưu khác nhau.</p>',15)),i(a),t[1]||(t[1]=n('<h3 id="bang-tra-cuu-nhanh-lua-chon-bieu-đo" tabindex="-1">Bảng tra cứu nhanh lựa chọn biểu đồ <a class="header-anchor" href="#bang-tra-cuu-nhanh-lua-chon-bieu-đo" aria-label="Permalink to “Bảng tra cứu nhanh lựa chọn biểu đồ”">​</a></h3><table tabindex="0"><thead><tr><th>Mục đích dữ liệu</th><th>Biểu đồ đề xuất</th><th>Không đề xuất</th><th>Lý do</th></tr></thead><tbody><tr><td>So sánh độ lớn</td><td>Biểu đồ cột, biểu đồ thanh</td><td>Biểu đồ tròn</td><td>Mắt người nhạy cảm với sự khác biệt về chiều dài hơn là góc độ</td></tr><tr><td>Thể hiện xu hướng</td><td>Biểu đồ đường, biểu đồ diện tích</td><td>Biểu đồ cột</td><td>Tính liên tục của đường ngụ ý tính liên tục của thời gian</td></tr><tr><td>Thể hiện tỷ trọng</td><td>Biểu đồ tròn (≤5 loại), biểu đồ cột chồng</td><td>Biểu đồ tròn 3D</td><td>Phối cảnh 3D làm biến dạng tỷ lệ diện tích</td></tr><tr><td>Thể hiện phân bố</td><td>Biểu đồ tần suất, biểu đồ hộp</td><td>Biểu đồ đường</td><td>Phân bố cần xem tần suất, không phải xu hướng</td></tr><tr><td>Thể hiện quan hệ</td><td>Biểu đồ phân tán, biểu đồ bong bóng</td><td>Biểu đồ cột</td><td>Quan hệ giữa hai biến liên tục cần không gian hai chiều</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Một quy tắc quyết định đơn giản</p><ul><li><strong>Một biến</strong> → Biểu đồ tần suất (phân bố) hoặc thẻ số (KPI)</li><li><strong>Hai biến</strong> → Biểu đồ đường (thời gian vs giá trị số) hoặc biểu đồ phân tán (giá trị vs giá trị)</li><li><strong>Nhiều danh mục</strong> → Biểu đồ cột (so sánh) hoặc biểu đồ tròn (tỷ trọng, ≤5 loại)</li><li><strong>Đa chiều</strong> → Biểu đồ radar hoặc biểu đồ tọa độ song song</li></ul></div><hr><h2 id="_2-nguyen-tac-thiet-ke-truc-quan-hoa-đe-du-lieu-tu-noi-len-cau-chuyen" tabindex="-1">2. Nguyên tắc thiết kế trực quan hóa: Để dữ liệu tự nói lên câu chuyện <a class="header-anchor" href="#_2-nguyen-tac-thiet-ke-truc-quan-hoa-đe-du-lieu-tu-noi-len-cau-chuyen" aria-label="Permalink to “2. Nguyên tắc thiết kế trực quan hóa: Để dữ liệu tự nói lên câu chuyện”">​</a></h2><p>Trực quan hóa tốt không phải là &quot;đẹp mắt&quot;, mà là &quot;dễ hiểu&quot;. Một số nguyên tắc kinh điển mà Edward Tufte đề xuất trong cuốn &quot;The Visual Display of Quantitative Information&quot; vẫn là tài liệu tham khảo quan trọng cho thiết kế trực quan hóa cho đến tận ngày nay.</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Mô tả</th><th>Ví dụ phản diện</th></tr></thead><tbody><tr><td>Tỷ lệ mực dữ liệu</td><td>Tỷ lệ &quot;mực&quot; dùng để hiển thị dữ liệu trong biểu đồ nên cao nhất có thể</td><td>Quá nhiều đường lưới, yếu tố trang trí</td></tr><tr><td>Tối thiểu hóa yếu tố phi dữ liệu</td><td>Loại bỏ các yếu tố trực quan không truyền đạt thông tin</td><td>Hiệu ứng 3D, đổ bóng, nền gradient</td></tr><tr><td>Tỷ lệ nhất quán</td><td>Trục tọa độ bắt đầu từ 0, vạch chia đều; nếu cắt đứt trục tọa độ phải ghi chú rõ ràng</td><td>Trục Y bắt đầu từ 95 nhưng không giải thích</td></tr><tr><td>Sử dụng màu sắc hợp lý</td><td>Dùng màu sắc để mã hóa thông tin, không phải trang trí</td><td>Màu cầu vồng biểu diễn dữ liệu có thứ tự</td></tr><tr><td>Ghi chú rõ ràng</td><td>Tiêu đề, nhãn trục, chú thích, đơn vị không thể thiếu</td><td>Không có đơn vị, không có phạm vi thời gian</td></tr></tbody></table><h3 id="_2-1-ty-le-muc-du-lieu-data-ink-ratio" tabindex="-1">2.1 Tỷ lệ mực dữ liệu（Data-Ink Ratio） <a class="header-anchor" href="#_2-1-ty-le-muc-du-lieu-data-ink-ratio" aria-label="Permalink to “2.1 Tỷ lệ mực dữ liệu（Data-Ink Ratio）”">​</a></h3><blockquote><p>Tỷ lệ &quot;mực&quot; dùng để thể hiện dữ liệu trong biểu đồ trên tổng &quot;mực&quot; nên cao nhất có thể.</p></blockquote><p>Nói đơn giản: <strong>Xóa bỏ mọi yếu tố không truyền đạt thông tin</strong>.</p><table tabindex="0"><thead><tr><th>Nên xóa bỏ</th><th>Nên giữ lại</th></tr></thead><tbody><tr><td>Hiệu ứng 3D, đổ bóng, gradient</td><td>Điểm dữ liệu, nhãn trục tọa độ</td></tr><tr><td>Đường lưới thừa</td><td>Đường tham chiếu quan trọng (như giá trị mục tiêu)</td></tr><tr><td>Biểu tượng trang trí</td><td>Chú thích (khi có nhiều chuỗi dữ liệu)</td></tr><tr><td>Màu nền hào nhoáng</td><td>Tiêu đề và đơn vị rõ ràng</td></tr></tbody></table><h3 id="_2-2-nguyen-tac-nhat-quan" tabindex="-1">2.2 Nguyên tắc nhất quán <a class="header-anchor" href="#_2-2-nguyen-tac-nhat-quan" aria-label="Permalink to “2.2 Nguyên tắc nhất quán”">​</a></h3><ul><li><strong>Màu sắc nhất quán</strong>: Cùng một chiều dữ liệu sử dụng cùng một màu trong các biểu đồ khác nhau, ví dụ &quot;doanh thu&quot; luôn dùng màu xanh dương</li><li><strong>Tỷ lệ nhất quán</strong>: Trục tọa độ nên bắt đầu từ 0, trừ khi có lý do chính đáng và ghi chú rõ ràng</li><li><strong>Thời gian nhất quán</strong>: Khoảng cách trên trục thời gian nên đều nhau, không vẽ các mốc thời gian không cách đều thành cách đều</li></ul><h3 id="_2-3-nguyen-tac-kha-nang-đoc" tabindex="-1">2.3 Nguyên tắc khả năng đọc <a class="header-anchor" href="#_2-3-nguyen-tac-kha-nang-đoc" aria-label="Permalink to “2.3 Nguyên tắc khả năng đọc”">​</a></h3><ul><li><strong>Tiêu đề phải nói lên kết luận</strong>: Không phải &quot;Doanh thu hàng tháng&quot;, mà là &quot;Doanh thu giảm liên tiếp 3 tháng&quot;</li><li><strong>Ghi chú các điểm quan trọng</strong>: Thêm ghi chú tại các giá trị ngoại lai, điểm uốn, hướng sự chú ý của người đọc</li><li><strong>Kiểm soát mật độ thông tin</strong>: Một biểu đồ truyền đạt 1-2 thông tin cốt lõi, không nên nhồi nhét quá nhiều</li></ul><div class="tip custom-block"><p class="custom-block-title">Ba quy tắc sử dụng màu sắc</p><ol><li><strong>Cùng một chỉ số dùng cùng một màu</strong>: Doanh thu trong tất cả biểu đồ đều dùng màu xanh dương, không lúc xanh lúc xanh lá</li><li><strong>Dữ liệu có thứ tự dùng màu gradient</strong>: Nhiệt độ từ thấp đến cao dùng gradient xanh dương→đỏ, không dùng màu rời rạc</li><li><strong>Cân đề xuất thân thiện với người mù màu</strong>: Khoảng 8% nam giới bị mù màu xanh đỏ, tránh chỉ dùng xanh đỏ để phân biệt thông tin quan trọng</li></ol></div><hr><h2 id="_3-bo-cuc-bang-đieu-khien-khac-canh-khac-mau" tabindex="-1">3. Bố cục bảng điều khiển: Khác cảnh, khác mẫu <a class="header-anchor" href="#_3-bo-cuc-bang-đieu-khien-khac-canh-khac-mau" aria-label="Permalink to “3. Bố cục bảng điều khiển: Khác cảnh, khác mẫu”">​</a></h2><p>Bảng điều khiển（Dashboard）là sự kết hợp hữu cơ của nhiều biểu đồ. Một bảng điều khiển tốt không phải là việc chất đầy các biểu đồ lại với nhau, mà là chọn mẫu bố cục phù hợp dựa trên ngữ cảnh sử dụng.</p>',19)),i(c),t[2]||(t[2]=n('<h3 id="bon-mau-bo-cuc-pho-bien" tabindex="-1">Bốn mẫu bố cục phổ biến <a class="header-anchor" href="#bon-mau-bo-cuc-pho-bien" aria-label="Permalink to “Bốn mẫu bố cục phổ biến”">​</a></h3><table tabindex="0"><thead><tr><th>Mẫu bố cục</th><th>Cấu trúc cốt lõi</th><th>Phù hợp với</th><th>Yêu cầu thiết kế</th></tr></thead><tbody><tr><td>Tổng quan toàn cục</td><td>Thẻ KPI + Biểu đồ xu hướng + Bảng chi tiết</td><td>Báo cáo ngày quản lý, bảng điều khiển vận hành</td><td>Chỉ số cốt lõi đặt lên trên cùng, nhìn thấy ngay các con số quan trọng</td></tr><tr><td>Phân tích so sánh</td><td>Bố cục đối xứng trái phải</td><td>Thử nghiệm A/B, phân tích so sánh</td><td>Giữ nhất quán chiều so sánh, làm nổi bật sự khác biệt</td></tr><tr><td>Phân tích chuyên sâu</td><td>Mở rộng từng tầng từ tổng hợp đến chi tiết</td><td>Phân tích bán hàng, phân tích hành vi người dùng</td><td>Hỗ trợ tương tác nhấp, đi sâu từng tầng</td></tr><tr><td>Giám sát thời gian thực</td><td>Số lớn + Đường cong thời gian thực + Trạng thái cảnh báo</td><td>Màn hình sự kiện quy mô lớn, giám sát máy chủ</td><td>Tự động làm mới, nền tối, phù hợp chiếu màn hình lớn</td></tr></tbody></table><h3 id="_5-nguyen-tac-thiet-ke-bang-đieu-khien" tabindex="-1">5 nguyên tắc thiết kế bảng điều khiển <a class="header-anchor" href="#_5-nguyen-tac-thiet-ke-bang-đieu-khien" aria-label="Permalink to “5 nguyên tắc thiết kế bảng điều khiển”">​</a></h3><ol><li><strong>Hỏi trước &quot;Ai đang xem&quot;</strong>: CEO xem chỉ số chiến lược, vận hành xem chỉ số quy trình, kỹ sư xem chỉ số kỹ thuật</li><li><strong>Quy tắc 5 giây</strong>: Người dùng nên hiểu được thông tin cốt lõi của bảng điều khiển trong vòng 5 giây</li><li><strong>Phân tầng thông tin</strong>: Quan trọng nhất đặt ở góc trên bên trái, thứ yếu đặt ở dưới</li><li><strong>Giảm cuộn trang</strong>: Hiển thị nội dung cốt lõi trên một màn hình, tránh người dùng phải cuộn để xem dữ liệu quan trọng</li><li><strong>Chừa khoảng trắng</strong>: Không lấp đầy mọi không gian, chừa khoảng trắng thích hợp giúp thị giác thoải mái hơn</li></ol><div class="tip custom-block"><p class="custom-block-title">Bảng điều khiển vs Báo cáo</p><ul><li><strong>Bảng điều khiển</strong>: Thời gian thực/gần thời gian thực, tương tác, hướng đến giám sát và ra quyết định nhanh</li><li><strong>Báo cáo</strong>: Tạo định kỳ (ngày/tuần/tháng), tĩnh, hướng đến phân tích chi tiết và lưu trữ</li></ul><p>Cả hai không phải mối quan hệ thay thế, mà là bổ sung cho nhau. Bảng điều khiển phát hiện vấn đề, báo cáo phân tích chuyên sâu.</p></div><hr><h2 id="_4-lua-chon-cong-cu-tu-thu-vien-code-đen-nen-tang-bi" tabindex="-1">4. Lựa chọn công cụ: Từ thư viện code đến nền tảng BI <a class="header-anchor" href="#_4-lua-chon-cong-cu-tu-thu-vien-code-đen-nen-tang-bi" aria-label="Permalink to “4. Lựa chọn công cụ: Từ thư viện code đến nền tảng BI”">​</a></h2><p>Công cụ trực quan hóa có thể được chia thành ba cấp: thư viện biểu đồ cấp code, thư viện biểu đồ phân tích dữ liệu, nền tảng BI. Việc chọn công cụ nào phụ thuộc vào độ phức tạp yêu cầu, yêu cầu tương tác và năng lực kỹ thuật của đội ngũ.</p><h3 id="_4-1-thu-vien-bieu-đo-cap-code" tabindex="-1">4.1 Thư viện biểu đồ cấp code <a class="header-anchor" href="#_4-1-thu-vien-bieu-đo-cap-code" aria-label="Permalink to “4.1 Thư viện biểu đồ cấp code”">​</a></h3><table tabindex="0"><thead><tr><th>Công cụ</th><th>Ngôn ngữ/Nền tảng</th><th>Đặc điểm</th><th>Phù hợp với</th></tr></thead><tbody><tr><td>ECharts</td><td>JavaScript</td><td>Sẵn sàng sử dụng, loại biểu đồ phong phú, tài liệu tiếng Trung hoàn thiện</td><td>Biểu đồ nhúng trong hệ thống doanh nghiệp</td></tr><tr><td>D3.js</td><td>JavaScript</td><td>Linh hoạt cấp thấp, có thể tùy chỉnh mọi hiệu ứng trực quan hóa</td><td>Trực quan hóa dữ liệu tùy chỉnh cao độ</td></tr><tr><td>Chart.js</td><td>JavaScript</td><td>Nhẹ, đơn giản, dễ tiếp cận</td><td>Nhu cầu biểu đồ đơn giản</td></tr><tr><td>Matplotlib</td><td>Python</td><td>Thư viện tiêu chuẩn tính toán khoa học, biểu đồ tĩnh</td><td>Phân tích dữ liệu, biểu đồ luận văn</td></tr><tr><td>Plotly</td><td>Python/JS</td><td>Biểu đồ tương tác, hỗ trợ 3D</td><td>Khám phá dữ liệu, Jupyter Notebook</td></tr></tbody></table><h3 id="_4-2-nen-tang-bi-khong-code-it-code" tabindex="-1">4.2 Nền tảng BI（Không code/Ít code） <a class="header-anchor" href="#_4-2-nen-tang-bi-khong-code-it-code" aria-label="Permalink to “4.2 Nền tảng BI（Không code/Ít code）”">​</a></h3><table tabindex="0"><thead><tr><th>Công cụ</th><th>Định vị</th><th>Lợi thế cốt lõi</th><th>Phù hợp với đội ngũ</th></tr></thead><tbody><tr><td>Grafana</td><td>Trực quan hóa giám sát</td><td>Hỗ trợ dữ liệu chuỗi thời gian tốt, tích hợp cảnh báo</td><td>Đội ngũ Vận hành/SRE</td></tr><tr><td>Metabase</td><td>BI nhẹ</td><td>Mã nguồn mở miễn phí, chỉ cần SQL để tạo biểu đồ</td><td>Xây dựng nhanh cho đội ngũ vừa và nhỏ</td></tr><tr><td>Apache Superset</td><td>BI doanh nghiệp</td><td>Mã nguồn mở, hỗ trợ nguồn dữ liệu lớn</td><td>Công ty có đội ngũ dữ liệu</td></tr><tr><td>Tableau</td><td>BI thương mại</td><td>Thao tác kéo thả, hiệu ứng trực quan hóa tốt</td><td>Nhà phân tích doanh nghiệp</td></tr><tr><td>Power BI</td><td>BI thương mại</td><td>Tích hợp tốt với hệ sinh thái Microsoft</td><td>Doanh nghiệp sử dụng công nghệ Microsoft</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Đề xuất lựa chọn</p><ul><li><strong>Nhà phát triển làm biểu đồ nhúng sản phẩm</strong> → ECharts（Hệ sinh thái tiếng Trung tốt）hoặc Chart.js（Kịch bản đơn giản）</li><li><strong>Nhà phân tích dữ liệu làm phân tích khám phá</strong> → Plotly + Jupyter hoặc Metabase</li><li><strong>Màn hình giám sát vận hành</strong> → Grafana（Tiêu chuẩn thực tế）</li><li><strong>Đội ngũ doanh nghiệp tự phân tích</strong> → Metabase（Mã nguồn mở）hoặc Tableau（Thương mại）</li><li><strong>Cần tùy chỉnh cao độ</strong> → D3.js（Đường cong học tập dốc, nhưng khả năng tạo hình cao nhất）</li></ul></div><hr><h2 id="_5-bay-pho-bien-nhung-bieu-đo-nay-đang-lua-ban" tabindex="-1">5. Bẫy phổ biến: Những biểu đồ này đang lừa bạn <a class="header-anchor" href="#_5-bay-pho-bien-nhung-bieu-đo-nay-đang-lua-ban" aria-label="Permalink to “5. Bẫy phổ biến: Những biểu đồ này đang lừa bạn”">​</a></h2><p>Trực quan hóa dữ liệu là con dao hai lưỡi: dùng tốt có thể tiết lộ sự thật, dùng không tốt sẽ tạo ra ảo giác. Dưới đây là những bẫy trực quan hóa phổ biến nhất, mỗi người làm dữ liệu đều nên có khả năng nhận diện.</p><h3 id="_5-1-cat-đut-truc-toa-đo" tabindex="-1">5.1 Cắt đứt trục tọa độ <a class="header-anchor" href="#_5-1-cat-đut-truc-toa-đo" aria-label="Permalink to “5.1 Cắt đứt trục tọa độ”">​</a></h3><p>Thay đổi điểm bắt đầu của trục Y từ 0 thành một số lớn sẽ làm cho sự khác biệt nhỏ trông giống như sự thay đổi khổng lồ.</p><table tabindex="0"><thead><tr><th>Kịch bản</th><th>Sự khác biệt thực tế</th><th>Cảm nhận thị giác</th></tr></thead><tbody><tr><td>Trục Y bắt đầu từ 0</td><td>Sản phẩm A 98 điểm, Sản phẩm B 95 điểm</td><td>Khoảng cách rất nhỏ</td></tr><tr><td>Trục Y bắt đầu từ 90</td><td>Cùng dữ liệu</td><td>A trông như gấp nhiều lần B</td></tr></tbody></table><p><strong>Khi nào có thể cắt đứt?</strong> Khi giá trị tuyệt đối của dữ liệu rất lớn nhưng thay đổi rất nhỏ (như giá cổ phiếu từ 100 lên 105), việc cắt đứt là hợp lý, nhưng phải ghi chú rõ ràng.</p><h3 id="_5-2-bai-phoi-canh-cua-bieu-đo-tron-3d" tabindex="-1">5.2 Bẫi phối cảnh của biểu đồ tròn 3D <a class="header-anchor" href="#_5-2-bai-phoi-canh-cua-bieu-đo-tron-3d" aria-label="Permalink to “5.2 Bẫi phối cảnh của biểu đồ tròn 3D”">​</a></h3><p>Phối cảnh 3D làm cho các phần gần người quan sát trông lớn hơn. Một phần 25% dưới góc nhìn 3D có thể trông giống như 35%.</p><p><strong>Giải pháp</strong>: Không bao giờ dùng biểu đồ tròn 3D. Dùng biểu đồ tròn thông thường hoặc biểu đồ vòng, hoặc đơn giản là dùng biểu đồ cột.</p><h3 id="_5-3-lam-dung-mau-sac" tabindex="-1">5.3 Lạm dụng màu sắc <a class="header-anchor" href="#_5-3-lam-dung-mau-sac" aria-label="Permalink to “5.3 Lạm dụng màu sắc”">​</a></h3><table tabindex="0"><thead><tr><th>Cách làm sai</th><th>Cách làm đúng</th></tr></thead><tbody><tr><td>Dùng xanh đỏ để biểu diễn dữ liệu</td><td>Dùng các phối màu an toàn cho người mù màu như xanh dương cam</td></tr><tr><td>Mỗi danh mục dùng màu khác nhau</td><td>Cùng một chuỗi dùng các sắc độ khác nhau của cùng một màu</td></tr><tr><td>Dùng màu mã hóa dữ liệu liên tục nhưng không thêm chú thích</td><td>Luôn cung cấp chú thích màu và ghi chú giá trị</td></tr><tr><td>Độ tương phản giữa màu nền và màu dữ liệu không đủ</td><td>Đảm bảo độ tương phản cấp WCAG AA</td></tr></tbody></table><h3 id="_5-4-cac-loi-pho-bien-khac" tabindex="-1">5.4 Các lỗi phổ biến khác <a class="header-anchor" href="#_5-4-cac-loi-pho-bien-khac" aria-label="Permalink to “5.4 Các lỗi phổ biến khác”">​</a></h3><table tabindex="0"><thead><tr><th>Bẫy</th><th>Vấn đề</th><th>Khắc phục</th></tr></thead><tbody><tr><td>Trục Y kép</td><td>Hai chỉ số không liên quan chia sẻ trục X, ngụ ý quan hệ nhân quả</td><td>Tách thành hai biểu đồ, hoặc giải thích rõ không có quan hệ nhân quả</td></tr><tr><td>Hiểu lầm về diện tích</td><td>Dùng bán kính hình tròn thay vì diện tích để biểu diễn giá trị</td><td>Khi giá trị nhân đôi thì diện tích nhân đôi, không phải bán kính</td></tr><tr><td>Trục thời gian không đều</td><td>Khoảng cách giữa tháng 1, tháng 3, tháng 12 giống nhau</td><td>Sắp xếp theo tỷ lệ thời gian thực tế</td></tr><tr><td>Quá nhiều danh mục</td><td>Biểu đồ tròn có 15 phần</td><td>Trên 5 danh mục thì dùng biểu đồ cột hoặc gộp &quot;Khác&quot;</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Quy tắc đạo đức của trực quan hóa</p><p>Mục đích của trực quan hóa là <strong>giúp hiểu</strong>, không phải <strong>thao túng nhận thức</strong>. Mỗi khi làm biểu đồ, hãy tự hỏi:</p><ul><li>Nếu tôi là người đọc, biểu đồ này có khiến tôi rút ra kết luận sai không?</li><li>Tôi có đang che giấu dữ liệu bất lợi không?</li><li>Trục tọa độ, tỷ lệ, màu sắc có trình bày dữ liệu một cách công bằng không?</li></ul></div><hr><h2 id="tom-tat" tabindex="-1">Tóm tắt <a class="header-anchor" href="#tom-tat" aria-label="Permalink to “Tóm tắt”">​</a></h2><p>Trực quan hóa dữ liệu là &quot;dặm cuối&quot; trong việc truyền đạt giá trị dữ liệu. Phân tích tốt đến đâu, nếu không thể được hiểu đúng, thì cũng như không có phân tích.</p><p>Nhìn lại các điểm chính của chương này:</p><ol><li><strong>Chọn đúng biểu đồ</strong>: Chọn loại biểu đồ dựa trên mục đích dữ liệu（so sánh, xu hướng, tỷ trọng, phân bố, quan hệ）</li><li><strong>Nguyên tắc thiết kế</strong>: Tỷ lệ mực dữ liệu cao, tính nhất quán, khả năng đọc là ba nguyên tắc cốt lõi</li><li><strong>Bố cục bảng điều khiển</strong>: Bốn mẫu tổng quan, so sánh, phân tích chuyên sâu, thời gian thực bao phủ hầu hết các kịch bản</li><li><strong>Lựa chọn công cụ</strong>: Từ ECharts đến Grafana, chọn dựa trên năng lực đội ngũ và độ phức tạp yêu cầu</li><li><strong>Tránh bẫy</strong>: Cắt đứt trục tọa độ, biểu đồ tròn 3D, lạm dụng màu sắc là những thủ thuật gây hiểu lầm phổ biến nhất</li></ol><h2 id="đoc-them" tabindex="-1">Đọc thêm <a class="header-anchor" href="#đoc-them" aria-label="Permalink to “Đọc thêm”">​</a></h2><ul><li><a href="https://www.edwardtufte.com/tufte/books_vdqi" target="_blank" rel="noreferrer">The Visual Display of Quantitative Information</a> - Kinh điển trực quan hóa của Edward Tufte</li><li><a href="https://echarts.apache.org/zh/index.html" target="_blank" rel="noreferrer">Tài liệu chính thức ECharts</a> - Thư viện biểu đồ tiếng Trung phổ biến nhất</li><li><a href="https://d3js.org/" target="_blank" rel="noreferrer">D3.js</a> - Thư viện trực quan hóa cấp thấp mạnh mẽ</li><li><a href="https://grafana.com/" target="_blank" rel="noreferrer">Grafana</a> - Tiêu chuẩn thực tế cho trực quan hóa giám sát</li><li><a href="https://www.data-to-viz.com/" target="_blank" rel="noreferrer">From Data to Viz</a> - Cây quyết định lựa chọn loại biểu đồ</li><li><a href="https://colorbrewer2.org/" target="_blank" rel="noreferrer">ColorBrewer</a> - Công cụ phối màu an toàn cho người mù màu</li></ul>',35))])}const y=u(d,[["render",o]]);export{k as __pageData,y as default};
